 const $=id=>document.getElementById(id),feedback=text=>{$('survivor-feedback').textContent=text;};
 function save(){try{localStorage.setItem(STORE,JSON.stringify({recipe,world}));}catch{feedback('Browser storage is full; current scene is not saved.');}}
