 await refreshPack();setInterval(refreshPack,60000);

 function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(running&&!document.hidden){acc+=dt;if(acc>=.25){world=advanceEncounter(world,graph,.25);acc-=.25;readout();}draw(dt);if(now-lastSave>2000){save();lastSave=now;}}requestAnimationFrame(frame);}requestAnimationFrame(frame);
 window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{last=performance.now();save();});
 window.RanchView?.register('survivors',()=>({recipe,people:Object.values(world.actors).length,time:world.encounter.time,running,activeHexes:8,overallHexes:allCells.length,gearReviewed:pack.assets.length,implemented:['shared actor movement','scene generation','relocation','undo','browser persistence']}));
